  /** Start a Caveman Code session. */
  startSession(input: AgentsStartSessionInput, options: AgentsCallOptions = {}): Promise<CodeSession> { return this.call('POST', `/code/sessions`, undefined, input, options); }
  /** List Caveman Code sessions. */
  listSessions(query: AgentsListSessionsQuery = {}, options: AgentsCallOptions = {}): Promise<AgentsListSessionsOutput> { return this.call('GET', `/code/sessions`, query, undefined, options); }
  /** Read a Caveman Code session. */
