  /** Read a session's events. */
  listEvents(sessionId: string, query: AgentsListEventsQuery = {}, options: AgentsCallOptions = {}): Promise<AgentsListEventsOutput> { return this.call('GET', `/code/sessions/${encodeURIComponent(String(sessionId))}/events`, query, undefined, options); }
  /** Create an agent. */
  createAgent(input: AgentsCreateAgentInput, options: AgentsCallOptions = {}): Promise<CodeAgent> { return this.call('POST', `/code/agents`, undefined, input, options); }
  /** List agents. */
  listAgents(query: AgentsListAgentsQuery = {}, options: AgentsCallOptions = {}): Promise<AgentsListAgentsOutput> { return this.call('GET', `/code/agents`, query, undefined, options); }
  /** Read an agent with its latest file. */
  getAgent(agentId: string, options: AgentsCallOptions = {}): Promise<CodeAgent> { return this.call('GET', `/code/agents/${encodeURIComponent(String(agentId))}`, undefined, undefined, options); }
  /** Update an agent's file or build. */
  updateAgent(agentId: string, input: AgentsUpdateAgentInput, options: AgentsCallOptions = {}): Promise<CodeAgent> { return this.call('POST', `/code/agents/${encodeURIComponent(String(agentId))}`, undefined, input, options); }
  /** List an agent's versions. */
