  /** Uploads a file (at most 100 MB) the key's sessions may attach; it mounts read-only at /mnt/session/uploads/<name>. */
  async uploadFile(name: string, content: Blob | Uint8Array, options: AgentsCallOptions & {mediaType?: string} = {}): Promise<CodeFile> {
    const form = new FormData();
    const blob = content instanceof Blob ? content : new Blob([new Uint8Array(content)], {type: options.mediaType ?? 'application/octet-stream'});
    form.append('file', blob, name);
    const timeout = AbortSignal.timeout(Math.max(this.timeout, 120000));
    const response = await this.transport(this.url('/code/files'), {
      method: 'POST', redirect: 'error', signal: options.signal ? AbortSignal.any([options.signal, timeout]) : timeout,
      headers: {authorization: 'Bearer ' + this.options.apiKey}, body: form,
    });
    const text = await response.text();
    let parsed: unknown = undefined;
    try { parsed = text ? JSON.parse(text) : undefined; } catch { parsed = undefined; }
    if (!response.ok) {
      const error = (parsed as {error?: {code?: string; message?: string}} | undefined)?.error;
      throw new CloudError(error?.code ?? 'cave_request_failed', error?.message ?? `Upload failed (${response.status}).`, response.status);
    }
    if (parsed === undefined) throw new CloudError('cave_response_invalid', 'The response is not JSON.', response.status);
    return parsed as CodeFile;
  }

  /** Downloads a file's bytes. */
  async downloadFile(fileId: string, options: AgentsCallOptions = {}): Promise<Uint8Array> {
    const timeout = AbortSignal.timeout(Math.max(this.timeout, 120000));
    const response = await this.transport(this.url(`/code/files/${encodeURIComponent(fileId)}/content`), {
      method: 'GET', redirect: 'error', signal: options.signal ? AbortSignal.any([options.signal, timeout]) : timeout,
      headers: {authorization: 'Bearer ' + this.options.apiKey},
    });
    if (!response.ok) {
      let error: {code?: string; message?: string} | undefined;
      try { error = (await response.json() as {error?: {code?: string; message?: string}}).error; } catch { error = undefined; }
      throw new CloudError(error?.code ?? 'cave_request_failed', error?.message ?? `Download failed (${response.status}).`, response.status);
    }
    return new Uint8Array(await response.arrayBuffer());
  }

  /**
   * Streams a session's events after `after` (server-sent events). The server ends a stream after 15 minutes, or once
   * an ended session has nothing more; call again with the last seq to continue.
   */
  async *streamEvents(sessionId: string, query: {after?: number} = {}, options: AgentsCallOptions = {}): AsyncGenerator<CodeStreamEvent> {
    const response = await this.transport(this.url(`/code/sessions/${encodeURIComponent(sessionId)}/events/stream`, query), {
      method: 'GET', redirect: 'error', signal: options.signal ?? null, headers: {authorization: 'Bearer ' + this.options.apiKey, accept: 'text/event-stream'},
    });
    if (!response.ok || !response.body) {
      let error: {code?: string; message?: string} | undefined;
      try { error = (await response.json() as {error?: {code?: string; message?: string}}).error; } catch { error = undefined; }
      throw new CloudError(error?.code ?? 'cave_request_failed', error?.message ?? `Stream failed (${response.status}).`, response.status);
    }
    const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
    let buffer = '';
    for (;;) {
      const {value, done} = await reader.read();
      if (done) return;
      buffer += value;
      let end: number;
      while ((end = buffer.indexOf('\n\n')) >= 0) {
        const frame = buffer.slice(0, end);
        buffer = buffer.slice(end + 2);
        let id = '', type = 'message', data = '';
        for (const line of frame.split('\n')) {
          if (line.startsWith('id: ')) id = line.slice(4);
          else if (line.startsWith('event: ')) type = line.slice(7);
          else if (line.startsWith('data: ')) data += line.slice(6);
        }
        if (type === 'error') {
          const failure = JSON.parse(data || '{}') as {code?: string};
          throw new CloudError(failure.code ?? 'cave_stream_failed', 'The event stream ended with an error.');
        }
        if (id) yield {seq: Number(id), type, data: JSON.parse(data || '{}') as Record<string, unknown>};
      }
    }
  }
